/* Ngữ pháp A2 · Elementary — sinh tự động bởi tools/build-grammar.py (npm run build:grammar), đừng sửa tay */
(window.FA_GRAMMAR_LESSONS = window.FA_GRAMMAR_LESSONS || {})["A2"] = [{"n":1,"title":"Reflexive pronouns","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Đại từ phản thân dùng khi người thực hiện hành động và người chịu tác động là cùng một đối tượng. Nếu dùng đại từ tân ngữ thường ở vị trí này, câu sẽ mang nghĩa khác hẳn, vì người chịu tác động trở thành một người khác. Nhóm đại từ này còn dùng để nhấn mạnh và trong cụm by oneself mang nghĩa tự mình làm."},{"p":"Cấu trúc chính: S + V + myself/yourself/himself/herself/itself/ourselves/yourselves/themselves"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She hurt herself while cooking. (Chủ ngữ và tân ngữ là cùng một người | Nhấn mạnh chính người đó | Nói về việc tự làm một mình)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Chủ ngữ và tân ngữ là cùng một người: Dùng khi hành động quay lại chính người thực hiện. (I cut myself.)"},{"p":"Nhấn mạnh chính người đó: Đại từ phản thân đứng sau chủ ngữ hoặc ở cuối câu để nhấn mạnh. (The director herself signed the letter.)"},{"p":"Nói về việc tự làm một mình: Cụm by + đại từ phản thân nghĩa là không có ai giúp. (He fixed the bike by himself.)"},{"p":"Động từ hay đi với đại từ phản thân: Enjoy, hurt, introduce, help, behave, teach thường cần đại từ phản thân. (Help yourself to some cake.)"},{"p":"Ghi nhớ: Dùng myself, yourself, himself khi chủ ngữ và tân ngữ là cùng một người."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + V + myself/yourself/himself/herself/itself/ourselves/yourselves/themselves"},{"table":[["Phân loại","Dạng từ / Công thức","Ví dụ"],["Số ít","myself, yourself, himself, herself, itself","He blamed himself."],["Số nhiều","ourselves, yourselves, themselves","They enjoyed themselves."],["Nhấn mạnh","S + đại từ phản thân + V, hoặc đặt ở cuối câu","I spoke to the manager myself."],["Tự làm một mình","by + đại từ phản thân","She lives by herself."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đối chiếu tân ngữ với chủ ngữ: Trùng thì dùng đại từ phản thân; khác thì dùng đại từ tân ngữ thường. (She hurt herself ↔ She hurt her (người khác))"},{"p":"02. Chọn dạng đúng theo số của chủ ngữ: Số ít kết thúc bằng -self, số nhiều kết thúc bằng -selves. (yourself (một người) ↔ yourselves (nhiều người))"},{"p":"03. Ngoại lệ với giới từ chỉ nơi chốn: Với giới từ chỉ nơi chốn, tiếng Anh vẫn dùng đại từ tân ngữ thường. (He put the bag beside him.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Chủ ngữ và tân ngữ trùng nhau","She hurt herself while cooking dinner.\n(Cô ấy bị thương khi đang nấu cơm.)","Người bị thương chính là cô ấy, nên bắt buộc dùng herself. Động từ hurt thuộc nhóm bất quy tắc giữ nguyên dạng ở quá khứ (hurt -hurt - hurt), nên ở đây là hurt chứ không phải hurts."],["Nghĩa đổi khi dùng sai","She hurt her while cooking dinner.\n(Cô ấy làm người kia bị thương khi đang nấu cơm.)","Her chỉ một người nữ khác, nên câu này mang nghĩa hoàn toàn khác."],["Số nhiều","The children enjoyed themselves at the party.\n(Các em rất vui ở buổi tiệc.)","Enjoy oneself là cụm cố định nghĩa là thấy vui; chủ ngữ số nhiều nên dùng themselves."],["Nhấn mạnh","The director herself signed the letter.\n(Chính giám đốc đã kí lá thư.)","Ở đây herself dùng để nhấn mạnh chính người đó chứ không giữ vai trò tân ngữ."],["Tự làm một mình","He repaired the bicycle by himself.\n(Anh ấy tự sửa xe đạp một mình.)","Cụm by himself nhấn mạnh không có ai giúp."],["Lời mời","Help yourself to some cake.\n(Bạn tự lấy bánh nhé.)","Help oneself là cụm cố định dùng khi mời ai tự lấy đồ ăn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba trường hợp dễ lẫn"},{"table":[["Dạng từ","Nghĩa / Chức năng","Ví dụ"],["herself (phản thân)","chính cô ấy chịu tác động","She saw herself in the mirror."],["her (tân ngữ)","một người nữ khác","She saw her at the station."],["each other","tác động lẫn nhau giữa hai người","They helped each other."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She hurt her while cooking. → Đã sửa: She hurt herself while cooking. — Chủ ngữ và tân ngữ là cùng một người nên phải dùng đại từ phản thân."},{"p":"Chưa đúng: The children enjoyed themself. → Đã sửa: The children enjoyed themselves. — Chủ ngữ số nhiều dùng dạng kết thúc bằng -selves."},{"p":"Chưa đúng: I live by my own. → Đã sửa: I live by myself. — Cụm đúng là by myself; dạng on my own cũng được, nhưng không nói by my own."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Tân ngữ có trùng với chủ ngữ hay không."},{"p":"Dạng -self cho số ít và -selves cho số nhiều."},{"p":"Ngoại lệ với giới từ chỉ nơi chốn."},{"p":"Each other dùng khi hai bên tác động lẫn nhau."}]}],"id":"a2-01"},{"n":2,"title":"Past simple","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Quá khứ đơn diễn tả việc đã xảy ra và đã kết thúc, thường kèm mốc thời gian xác định như yesterday, last week, in 2020. Động từ có hai nhóm: động từ có quy tắc thêm -ed, động từ bất quy tắc đổi hình thức và phải học theo bảng. Trong câu phủ định và nghi vấn, dấu hiệu quá khứ chuyển sang trợ động từ did."},{"p":"Cấu trúc chính: S + V2/V-ed"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): We visited Hoi An last summer. (Hành động đã kết thúc trong quá khứ | Kể chuỗi sự việc theo trình tự | Thói quen đã dứt trong quá khứ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Hành động đã kết thúc trong quá khứ: Thường đi với mốc thời gian cụ thể đã qua. (I met him yesterday.)"},{"p":"Kể chuỗi sự việc theo trình tự: Các động từ quá khứ đơn nối tiếp nhau tạo nên mạch kể. (She opened the door, turned on the light and sat down.)"},{"p":"Thói quen đã dứt trong quá khứ: Diễn tả việc từng lặp lại nhưng nay không còn. (We played football every afternoon.)"},{"p":"Trạng thái trong quá khứ: Dùng với was, were và các động từ chỉ trạng thái. (He lived in Hue for ten years.)"},{"p":"Ghi nhớ: Nói về hành động đã kết thúc tại một thời điểm xác định trong quá khứ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + V2/V-ed"},{"table":[["Dạng thức","Công thức / Quy tắc","Ví dụ"],["Có quy tắc","V + -ed | -d sau -e | phụ âm + y → -ied | nhân đôi phụ âm cuối","work → worked, live → lived, study → studied, stop → stopped"],["Bất quy tắc","đổi hình thức, không theo quy tắc","go → went, see → saw, buy → bought, take → took, find → found"],["Phủ định","S + did not (didn't) + V nguyên mẫu","She didn't come."],["Nghi vấn","Did + S + V nguyên mẫu?","Did you see it?"],["Bất quy tắc hay gặp","fall → fell, begin → began, go → went, see → saw (phải thuộc, không thêm -ed)","Emissions fell sharply. / Monitoring began long before the plant opened."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định nhóm động từ: Động từ có quy tắc thêm -ed; động từ bất quy tắc dùng cột thứ hai trong bảng động từ, phải học thuộc từng dạng. (watch → watched / go → went / send → sent / hear → heard/ read → read (viết như nhau, đọc khác))"},{"p":"02. Áp quy tắc chính tả cho đuôi -ed: Động từ kết thúc bằng -e chỉ thêm -d; phụ âm + y đổi thành -ied; động từ một âm tiết kết thúc bằng nguyên âm + phụ âm thì nhân đôi phụ âm cuối. (plan → planned)"},{"p":"03. Dùng did trong câu phủ định và nghi vấn: Khi đã có did, động từ chính trở về dạng nguyên mẫu và không còn dấu hiệu quá khứ. (Did you go? (không phải Did you went))"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Mốc thời gian xác định","We visited Hoi An last summer.\n(Hè năm ngoái chúng tôi đi Hội An.)","Last summer là mốc đã qua nên động từ phải ở quá khứ đơn, không dùng hiện tại đơn."],["Động từ bất quy tắc","She went to the market and bought some fish.\n(Cô ấy ra chợ và mua một ít cá.)","Go → went và buy → bought đều là động từ bất quy tắc, không thêm -ed."],["Có quy tắc, nhân đôi phụ âm","The bus stopped in front of the school.\n(Xe buýt dừng trước cổng trường.)","Stop có một âm tiết, kết thúc bằng nguyên âm + phụ âm, nên nhân đôi p trước khi thêm -ed."],["Phủ định","He didn't finish his homework last night.\n(Tối qua anh ấy không làm xong bài tập.)","Didn't đã mang dấu hiệu quá khứ nên finish giữ dạng nguyên mẫu, không phải didn't finished. Homework là danh từ không đếm được nên luôn viết homework, không bao giờ thêm -s."],["Nghi vấn","Did you see the film yesterday?\n(Hôm qua bạn có xem bộ phim đó không?)","Did đứng đầu câu, động từ chính see trở về nguyên mẫu."],["Chuỗi sự việc","She opened the door, turned on the light and sat down.\n(Cô ấy mở cửa, bật đèn rồi ngồi xuống.)","Ba động từ quá khứ đơn nối tiếp nhau thể hiện trình tự trước sau."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Động từ bất quy tắc thường dùng"},{"table":[["Cặp động từ","Đặc điểm","Ví dụ"],["go → went / see → saw / do → did","đổi hoàn toàn","I saw her yesterday."],["buy → bought / teach → taught /think → thought","nhóm đổi thành -ought/-aught","He taught us last year."],["cut → cut / put → put / read → read","giữ nguyên hình thức viết","She put it there."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: We visit Hoi An last summer. → Đã sửa: We visited Hoi An last summer. — Có mốc thời gian quá khứ thì động từ phải ở dạng quá khứ."},{"p":"Chưa đúng: Did you went to the party? → Đã sửa: Did you go to the party? — Did đã mang dấu hiệu quá khứ nên động từ chính về nguyên mẫu."},{"p":"Chưa đúng: She didn't bought anything. → Đã sửa: She didn't buy anything. — Sau didn't luôn là động từ nguyên mẫu."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu có mốc thời gian quá khứ hay không."},{"p":"Động từ thuộc nhóm có quy tắc hay bất quy tắc."},{"p":"Đuôi -ed viết đúng chính tả."},{"p":"Câu phủ định và nghi vấn dùng did với động từ nguyên mẫu."}]}],"id":"a2-02"},{"n":3,"title":"Was, were & past questions","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ở quá khứ, động từ to be có hai dạng: was cho I, he, she, it và were cho you, we, they. To be tự tạo câu hỏi và câu phủ định bằng cách đảo hoặc thêm not, trong khi động từ thường phải nhờ trợ động từ did. Lẫn hai hệ thống này là lỗi thường gặp nhất ở trình độ A2."},{"p":"Cấu trúc chính: Was/Were + S …? | Did + S + V …?"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Were you at home last night? (Miêu tả trạng thái trong quá khứ | Nêu vị trí trong quá khứ | Hỏi về sự việc đã qua)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Miêu tả trạng thái trong quá khứ: Was và were nối chủ ngữ với tính từ hoặc danh từ ở thời điểm đã qua. (The film was excellent.)"},{"p":"Nêu vị trí trong quá khứ: Sau was, were là trạng ngữ chỉ nơi chốn. (They were at the stadium.)"},{"p":"Hỏi về sự việc đã qua: Với to be thì đảo was/were; với động từ thường thì dùng did. (Was it cold? / Did it rain?)"},{"p":"Nói về sự tồn tại trong quá khứ: Cấu trúc there was và there were nêu sự tồn tại trong quá khứ. (There were many people at the market.)"},{"p":"Ghi nhớ: Was dùng cho chủ ngữ số ít, were cho số nhiều; câu hỏi với động từ thường dùng did."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: Was/Were + S …? | Did + S + V …?"},{"table":[["Dạng thức","Công thức / Dạng từ","Ví dụ"],["Khẳng định","I/he/she/it + was | you/we/they + were","She was tired."],["Phủ định","wasn't | weren't","They weren't ready."],["Nghi vấn với to be","Was/Were + S …?","Were you at home?"],["Nghi vấn với động từ thường","Did + S + V nguyên mẫu …?","Did you watch the match?"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định động từ chính của câu: To be tự đảo để hỏi; động từ thường cần did. (Were you busy? ↔ Did you work?)"},{"p":"02. Chọn was hay were theo chủ ngữ: I, he, she, it và danh từ số ít dùng was; you và các chủ ngữ số nhiều dùng were. (The children were…)"},{"p":"03. Đặt từ hỏi lên đầu nếu có: Trật tự là từ hỏi + was/were hoặc did + chủ ngữ. (Where were you? /Where did you go?)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Nghi vấn với to be","Were you at home last night?\n(Tối qua bạn có ở nhà không?)","Động từ chính là to be nên đảo were lên trước chủ ngữ, không dùng did."],["Khẳng định số ít","The film was really interesting.\n(Bộ phim rất hay.)","The film là danh từ số ít nên dùng was."],["Phủ định số nhiều","The shops weren't open on Sunday.\n(Chủ nhật các cửa hàng không mở.)","Chủ ngữ số nhiều dùng weren't; không cần didn't."],["Nghi vấn với động từ thường","Did you watch the match yesterday?\n(Hôm qua bạn có xem trận đấu không?)","Watch là động từ thường nên câu hỏi dùng did với động từ nguyên mẫu."],["Câu hỏi có từ hỏi","Where were you this morning? — I was at the clinic.\n(Sáng nay bạn ở đâu? — Tôi ở phòng khám.)","Từ hỏi where đứng trước were, rồi mới đến chủ ngữ."],["There was và there were","There was a storm last night and there were no buses this morning.\n(Đêm qua có bão và sáng nay không có xe buýt.)","Động từ hòa hợp với danh từ đi sau: a storm số ít dùng was, no buses số nhiều dùng were."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai hệ thống câu hỏi ở quá khứ"},{"table":[["Loại động từ","Quy tắc","Ví dụ"],["to be","đảo was/were, không dùng did","Was she late?"],["động từ thường","dùng did + nguyên mẫu","Did she arrive late?"],["động từ khuyết thiếu","đảo chính nó","Could she come?"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Did you be at home last night? → Đã sửa: Were you at home last night? — To be không dùng did để tạo câu hỏi, mà tự đảo lên trước chủ ngữ."},{"p":"Chưa đúng: The children was in the garden. → Đã sửa: The children were in the garden. — Children là danh từ số nhiều nên dùng were."},{"p":"Chưa đúng: I didn't be tired. → Đã sửa: I wasn't tired. — Phủ định của to be là thêm not trực tiếp, không dùng didn't."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Động từ chính của câu là to be hay động từ thường."},{"p":"Was và were chọn đúng theo chủ ngữ."},{"p":"Không dùng did với to be."},{"p":"Từ hỏi đứng trước was, were hoặc did."}]}],"id":"a2-03"},{"n":4,"title":"Prepositions of movement","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tiếng Anh phân biệt rõ giới từ chỉ vị trí tĩnh và giới từ chỉ hướng di chuyển. In nghĩa là đang ở bên trong, còn into nghĩa là đi từ ngoài vào trong. Nhầm hai nhóm này làm câu mất nghĩa chuyển động, và đây là lỗi rất phổ biến vì tiếng Việt dùng chung từ trong cho cả hai trường hợp."},{"p":"Cấu trúc chính: động từ chuyển động + into/out of/across/through/along/up/down"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She walked into the room and put her bag on the table. (Đi vào và đi ra | Băng qua một không gian | Đi theo một đường)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Đi vào và đi ra: Into chỉ hướng vào trong, out of chỉ hướng ra ngoài. (He came into the office. / He went out of the building.)"},{"p":"Băng qua một không gian: Across đi qua một bề mặt, through đi xuyên qua bên trong một không gian. (We walked across the bridge. / We drove through the tunnel.)"},{"p":"Đi theo một đường: Along đi dọc theo, past đi ngang qua mà không dừng. (Walk along this street and go past the bank.)"},{"p":"Lên và xuống, đến và rời: Up, down chỉ chiều cao; to chỉ điểm đến, from chỉ điểm khởi hành. (She ran up the stairs. / I flew from Hue to Hanoi.)"},{"p":"Ghi nhớ: Into, out of, across, through, along, onto chỉ hướng di chuyển, khác với in và on chỉ vị trí tĩnh."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: động từ chuyển động + into/out of/across/through/along/up/down"},{"table":[["Nhóm hướng","Danh sách giới từ","Ví dụ"],["Vào và ra","into, out of, onto, off","jump into the pool, get off the bus"],["Qua","across, through, over, past","swim across the river, climb over the wall"],["Theo đường và chiều","along, up, down, around","cycle along the river, walk down the hill"],["Điểm đến và điểm đi","to, from, towards, as far as","walk towards the station"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt vị trí và chuyển động: Vị trí tĩnh dùng in, on, at; chuyển động dùng into, onto, to. (She is in the room. ↔ She walked into the room.)"},{"p":"02. Chọn giới từ theo hình dung không gian: Across là qua bề mặt, through là xuyên qua bên trong, over là vượt lên trên. (across the field / through the forest / over the fence)"},{"p":"03. Nhớ các cụm cố định với phương tiện: Get on và get off dùng cho xe buýt, tàu, máy bay; get into và get out of dùng cho xe hơi. (get on the train / get into the taxi)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Chuyển động và vị trí trong một câu","She walked into the room and put her bag on the table.\n(Cô ấy bước vào phòng và đặt túi lên bàn.)","Into chỉ hướng đi vào, còn on chỉ vị trí tĩnh của chiếc túi sau khi đã đặt xuống."],["Qua bề mặt","We walked across the bridge to the other bank.\n(Chúng tôi đi bộ qua cầu sang bờ bên kia.)","Across dùng khi đi từ bên này sang bên kia một bề mặt."],["Xuyên qua","The train went through a long tunnel.\n(Tàu chạy xuyên qua một đường hầm dài.)","Through dùng khi đi vào bên trong rồi ra khỏi một không gian."],["Theo một đường","Walk along this street and go past the post office.\n(Đi dọc con phố này rồi đi qua bưu điện.)","Along là đi dọc theo, past là đi ngang qua mà không dừng lại."],["Lên và xuống","She ran up the stairs and then came down again.\n(Cô ấy chạy lên cầu thang rồi lại đi xuống.)","Up và down chỉ chiều cao của chuyển động."],["Phương tiện","We got on the bus in Hue and got off in Da Nang.\n(Chúng tôi lên xe buýt ở Huế và xuống ở Đà Nẵng.)","Xe buýt, tàu, máy bay dùng get on và get off; xe hơi dùng get into và get out of."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Giới từ tĩnh và giới từ chuyển động"},{"table":[["Cặp giới từ","Nghĩa","Ví dụ"],["in ↔ into","ở trong ↔ đi vào trong","He is in the car. ↔ He got into the car."],["on ↔ onto","ở trên ↔ leo lên trên","The cat is on the roof. ↔ The cat jumped onto the roof."],["at ↔ to","ở tại ↔ đi đến","She is at school. ↔ She goes to school."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She walked in the room and sat down. → Đã sửa: She walked into the room and sat down. — Câu nói về hướng đi vào nên dùng into; in chỉ vị trí đang ở bên trong."},{"p":"Chưa đúng: We drove across the tunnel. → Đã sửa: We drove through the tunnel. — Đường hầm là không gian kín nên dùng through, không dùng across."},{"p":"Chưa đúng: I got on the taxi at the airport. → Đã sửa: I got into the taxi at the airport. — Xe hơi và taxi dùng get into, còn get on dùng cho xe buýt và tàu."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu nói về vị trí tĩnh hay về hướng chuyển động."},{"p":"Giới từ khớp với hình dung không gian của hành động."},{"p":"Các cụm cố định với phương tiện dùng đúng."},{"p":"Không dùng in, on, at cho động từ chỉ chuyển động có hướng."}]}],"id":"a2-04"},{"n":5,"title":"Will & be going to","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tiếng Anh không có một thì tương lai duy nhất. Will diễn tả quyết định nảy ra ngay lúc nói, lời hứa, lời đề nghị và dự đoán thuần chủ quan. Be going to diễn tả dự định đã có từ trước và dự đoán dựa trên dấu hiệu đang thấy. Chọn đúng cấu trúc là chọn đúng sắc thái, không phải chọn đúng thời điểm."},{"p":"Cấu trúc chính: will + V nguyên mẫu | am/is/are going to + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): We are going to visit our grandparents this weekend. (Quyết định tức thì với will | Dự định có sẵn với be going to | Dự đoán)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Quyết định tức thì với will: Dùng khi vừa nghĩ ra điều gì ngay trong lúc nói. (It's cold. I'll close the window.)"},{"p":"Dự định có sẵn với be going to: Việc đã được nghĩ tới hoặc sắp xếp trước khi cuộc hội thoại diễn ra. (We are going to move house next month.)"},{"p":"Dự đoán: Will cho dự đoán chủ quan; be going to cho dự đoán có bằng chứng trước mắt. (I think it will rain. / Look at those clouds — it's going to rain.)"},{"p":"Lời hứa, lời đề nghị, lời mời: Thường dùng will cho lời hứa và đề nghị giúp đỡ (I'll help you.), dùng Shall I…? để đề nghị giúp (Shall I carry that?) và Shall we…? để gợi ý; không dùng be going to cho các sắc thái này."},{"p":"Ghi nhớ: Will dùng cho quyết định tức thì và dự đoán; be going to dùng cho dự định đã có và dự đoán có căn cứ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: will + V nguyên mẫu | am/is/are going to + V"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Will khẳng định","S + will ('ll) + V nguyên mẫu","She'll call you later."],["Will phủ định và nghi vấn","will not (won't) + V | Will + S + V?","He won't come. / Will you help me?"],["Be going to","S + am/is/are (not) going to + V","They are going to study abroad."],["Nghi vấn be going to","Am/Is/Are + S + going to + V?","Are you going to join us?"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định sắc thái cần diễn đạt: Dự định có sẵn hoặc dấu hiệu rõ ràng thì dùng be going to; quyết định tức thì, lời hứa, dự đoán chủ quan thì dùng will. (I'm going to buy it. (đã định) ↔ I'll buy it. (vừa quyết))"},{"p":"02. Giữ động từ nguyên mẫu sau will: Will là động từ khuyết thiếu nên không thêm to và không chia theo chủ ngữ. (will go, không phải will to go)"},{"p":"03. Chia to be trong be going to: Phần going to giữ nguyên, chỉ to be biến đổi. (He is going to… / They are going to…)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Dự định có sẵn","We are going to visit our grandparents this weekend.\n(Cuối tuần này chúng tôi sẽ về thăm ông bà.)","Kế hoạch đã có trước lúc nói nên dùng be going to."],["Quyết định tức thì","It's cold in here. I'll close the window.\n(Trong này lạnh. Tôi đóng cửa sổ nhé.)","Quyết định nảy ra ngay lúc nói nên dùng will, thường ở dạng rút gọn 'll."],["Dự đoán có căn cứ","Look at those clouds — it's going to rain.\n(Nhìn mấy đám mây kia xem, trời sắp mưa đấy.)","Có bằng chứng trước mắt nên be going to tự nhiên hơn will."],["Dự đoán chủ quan","I think she will pass the exam easily.\n(Tôi nghĩ cô ấy sẽ đỗ dễ dàng.)","Sau các cụm nêu ý kiến như I think, I hope thường dùng will."],["Lời hứa","I won't tell anyone about this.\n(Tôi sẽ không kể với ai chuyện này.)","Lời hứa dùng will; dạng phủ định rút gọn là won't."],["Nghi vấn be going to","Are you going to apply for that job?\n(Bạn có định xin việc đó không?)","Câu hỏi đảo to be lên trước chủ ngữ, phần going to giữ nguyên."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chọn will hay be going to"},{"table":[["Tình huống","Cấu trúc","Ví dụ"],["quyết định ngay lúc nói","will","I'll have the chicken, please."],["dự định đã có","be going to","I'm going to learn Japanese this year."],["dự đoán có dấu hiệu","be going to","He's going to fall!"],["lời hứa, đề nghị giúp","will","I'll give you a hand."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: We will to visit our grandparents. → Đã sửa: We will visit our grandparents. — Will là động từ khuyết thiếu nên theo sau là động từ nguyên mẫu không to."},{"p":"Chưa đúng: She wills come tomorrow. → Đã sửa: She will come tomorrow. — Will không chia theo chủ ngữ, không thêm -s."},{"p":"Chưa đúng: I am going to tell you a secret, I promise. → Đã sửa: I will tell you a secret, I promise. — Lời hứa dùng will chứ không dùng be going to."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Sắc thái cần diễn đạt là dự định, quyết định hay dự đoán."},{"p":"Sau will là động từ nguyên mẫu không to."},{"p":"To be trong be going to đã chia đúng theo chủ ngữ."},{"p":"Không dùng be going to cho lời hứa hoặc lời đề nghị."}]}],"id":"a2-05"},{"n":6,"title":"Present perfect: experience","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Hiện tại hoàn thành nối quá khứ với hiện tại: việc đã xảy ra nhưng điều người nói quan tâm là kết quả hoặc kinh nghiệm tính đến lúc này. Vì vậy thì này không đi với mốc thời gian đã kết thúc. Hình thức gồm have hoặc has cộng với quá khứ phân từ, tức cột thứ ba của bảng động từ."},{"p":"Cấu trúc chính: S + have/has + V3"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): I have visited Hanoi three times. (Nêu trải nghiệm trong đời | Việc vừa xảy ra, còn để lại kết quả | Đếm số lần tính đến hiện tại)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu trải nghiệm trong đời: Không nêu thời điểm vì điều quan trọng là đã từng hay chưa từng. (I have been to Japan.)"},{"p":"Việc vừa xảy ra, còn để lại kết quả: Thường đi với just, already, yet. (She has just finished her report.)"},{"p":"Đếm số lần tính đến hiện tại: Số lần có thể còn tăng thêm vì khoảng thời gian chưa kết thúc. (He has failed the test twice.)"},{"p":"Khoảng thời gian chưa kết thúc: Đi với today, this week, this year khi những khoảng này vẫn đang diễn ra. (I have read two books this month.)"},{"p":"Ghi nhớ: Nói về trải nghiệm hoặc kết quả tính đến hiện tại mà không nêu thời điểm cụ thể."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: S + have/has + V3"},{"table":[["Dạng thức","Công thức","Ví dụ"],["Khẳng định","I/you/we/they + have + V3 | he/she/it + has + V3","She has finished."],["Phủ định","have not (haven't) / has not (hasn't) + V3","They haven't arrived."],["Nghi vấn","Have/Has + S + V3?","Have you eaten?"],["Quá khứ phân từ","V-ed với động từ có quy tắc | cột 3 với động từ bất quy tắc","work → worked, go → gone, see → seen, write → written, make → made"],["V3 bất quy tắc hay gặp","break → broken, go → gone, write → written, take → taken","Someone has broken the window."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn have hay has theo chủ ngữ: He, she, it và danh từ số ít dùng has; các chủ ngữ còn lại dùng have. (My sister has…)"},{"p":"02. Dùng quá khứ phân từ: Với động từ bất quy tắc, cột thứ hai và cột thứ ba thường khác nhau. (I have seen it, không phải I have saw it)"},{"p":"03. Kiểm tra mốc thời gian trong câu: Yesterday, last year, in 2020 đòi hỏi quá khứ đơn chứ không phải hiện tại hoàn thành. (I saw it yesterday.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Trải nghiệm","I have visited Hanoi three times.\n(Tôi đã đến Hà Nội ba lần.)","Không nêu thời điểm vì điều quan trọng là số lần tính đến hiện tại và con số này còn có thể tăng."],["Chưa từng","She has never eaten durian.\n(Cô ấy chưa bao giờ ăn sầu riêng.)","Never đứng giữa has và quá khứ phân từ, mang nghĩa phủ định sẵn."],["Vừa xảy ra","He has just finished his homework.\n(Anh ấy vừa làm xong bài tập.)","Just nhấn mạnh việc vừa hoàn tất và kết quả còn hiện hữu."],["Nghi vấn","Have you ever been to Japan?\n(Bạn từng đến Nhật chưa?)","Ever dùng trong câu hỏi về trải nghiệm; been là quá khứ phân từ của be."],["Khoảng thời gian chưa kết thúc","We have read two books this month.\n(Tháng này chúng tôi đã đọc hai quyển sách.)","This month vẫn đang diễn ra nên dùng hiện tại hoàn thành."],["Kết quả còn hiện hữu","I have lost my keys, so I can't get in.\n(Tôi mất chìa khoá rồi nên không vào được.)","Việc mất xảy ra trong quá khứ nhưng hậu quả vẫn tồn tại ở hiện tại."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hiện tại hoàn thành và quá khứ đơn"},{"table":[["Cấu trúc / Từ","Đặc điểm","Ví dụ"],["have/has + V3","không nêu thời điểm, quan tâm kết quả","I have seen that film."],["V2/V-ed","có mốc thời gian đã kết thúc","I saw that film last night."],["been / gone","been là đã đi và đã về, gone là đã đi và còn ở đó","She has been to Hue. ↔ She has gone to Hue."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: I have visited Hanoi last year. → Đã sửa: I visited Hanoi last year. — Last year là mốc đã kết thúc nên phải dùng quá khứ đơn."},{"p":"Chưa đúng: She has went to the market. → Đã sửa: She has gone to the market. — Sau has phải là quá khứ phân từ gone, không phải quá khứ đơn went."},{"p":"Chưa đúng: He have finished his work. → Đã sửa: He has finished his work. — Ngôi thứ ba số ít dùng has."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu có mốc thời gian đã kết thúc hay không."},{"p":"Have hoặc has chọn đúng theo chủ ngữ."},{"p":"Động từ ở dạng quá khứ phân từ, không phải quá khứ đơn."},{"p":"Trạng từ như just, never, ever đặt giữa trợ động từ và động từ chính."}]}],"id":"a2-06"},{"n":7,"title":"Must, have to & should","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Ba cấu trúc này đều nói về việc nên hay phải làm, nhưng mức độ khác nhau. Must là bắt buộc mạnh, thường do người nói tự thấy cần thiết. Have to là bắt buộc do hoàn cảnh hoặc quy định bên ngoài. Should là lời khuyên, không mang tính ép buộc. Dạng phủ định của must và have to mang nghĩa hoàn toàn khác nhau, đây là điểm dễ sai nhất."},{"p":"Cấu trúc chính: must/should + V nguyên mẫu | have/has to + V"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): You should see a doctor. (Bắt buộc mạnh với must | Bắt buộc từ quy định bên ngoài | Lời khuyên với should)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Bắt buộc mạnh với must: Dùng cho nội quy, biển báo và điều người nói cho là thiết yếu. (You must wear a helmet.)"},{"p":"Bắt buộc từ quy định bên ngoài: Have to chia theo chủ ngữ và có dạng ở mọi thì, khác với must. (She has to work on Saturdays.)"},{"p":"Lời khuyên với should: Mức độ nhẹ, có thể làm hoặc không. (You should rest more.)"},{"p":"Phủ định hai nghĩa khác nhau: Mustn't là cấm; don't have to là không cần thiết. (You mustn't smoke here. ↔ You don't have to come.)"},{"p":"Ghi nhớ: Must chỉ bắt buộc từ bên trong, have to chỉ bắt buộc từ quy định bên ngoài, should đưa ra lời khuyên."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: must/should + V nguyên mẫu | have/has to + V"},{"table":[["Động từ","Công thức","Ví dụ"],["must","S + must + V nguyên mẫu (không chia theo chủ ngữ)","He must leave now."],["have to","I/you/we/they + have to | he/she/it + has to","She has to study."],["should","S + should (not) + V nguyên mẫu","You shouldn't worry."],["Phủ định","mustn't = cấm | don't/doesn't have to = không cần","You mustn't be late. ↔ You don't have to pay."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định nguồn của sự bắt buộc: Người nói tự thấy cần thì dùng must; quy định bên ngoài thì dùng have to. (I must finish this. ↔ I have to wear a uniform.)"},{"p":"02. Giữ nguyên mẫu không to sau must: Riêng have to thì phần to đã nằm trong cấu trúc. (should go /have to go)"},{"p":"03. Chọn dạng phủ định theo nghĩa muốn diễn đạt: Cấm thì dùng mustn't; không cần thiết thì dùng don't have to. (You mustn't touch it. ↔ You don't have to buy it.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Lời khuyên","You should see a doctor about that cough.\n(Bạn nên đi khám về cơn ho đó.)","Should là lời khuyên và động từ theo sau ở dạng nguyên mẫu không to."],["Bắt buộc mạnh","Passengers must wear a seatbelt at all times.\n(Hành khách phải luôn cài dây an toàn.)","Must dùng cho nội quy; động từ wear giữ nguyên dạng với mọi chủ ngữ."],["Quy định bên ngoài","She has to work on Saturdays because of her new job.\n(Cô ấy phải làm việc vào thứ Bảy vì công việc mới.)","Have to chia theo chủ ngữ nên she kéo theo has to."],["Cấm","You mustn't use your phone during the exam.\n(Bạn không được dùng điện thoại trong lúc thi.)","Mustn't mang nghĩa cấm tuyệt đối, không phải không cần."],["Không cần thiết","You don't have to come early; the show starts at eight.\n(Bạn không cần đến sớm, buổi diễn tám giờ mới bắt đầu.)","Don't have to chỉ sự không cần thiết, hoàn toàn khác mustn't."],["Lời khuyên phủ định","You shouldn't eat so much sugar.\n(Bạn không nên ăn nhiều đường như vậy.)","Shouldn't là lời khuyên không nên, nhẹ hơn mustn't rất nhiều."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba mức độ và hai dạng phủ định"},{"table":[["Cấu trúc","Sắc thái / Cách dùng","Ví dụ"],["must","bắt buộc mạnh, không chia theo chủ ngữ","You must stop here."],["have to","bắt buộc do bên ngoài, chia theo chủ ngữ và có mọi thì","He had to leave early."],["mustn't","cấm làm","You mustn't open that door."],["don't have to","không cần làm","You don't have to wait."],["ought to","tương đương should (điều nên làm), sắc thái trang trọng hơn; sau nó là động từ nguyên mẫu có to","Every claim ought to be supported by a citation."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: You should to see a doctor. → Đã sửa: You should see a doctor. — Should là động từ khuyết thiếu nên theo sau là động từ nguyên mẫu không to."},{"p":"Chưa đúng: She must to work on Saturdays. → Đã sửa: She has to work on Saturdays. — Must không đi với to; nếu muốn nói về quy định công việc thì have to tự nhiên hơn."},{"p":"Chưa đúng: You mustn't pay, it's free. → Đã sửa: You don't have to pay, it's free. — Mustn't là cấm; ý ở đây là không cần thiết nên phải dùng don't have to."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Sự bắt buộc đến từ bên trong hay từ quy định bên ngoài."},{"p":"Động từ sau must và should ở dạng nguyên mẫu không to."},{"p":"Have to đã chia đúng theo chủ ngữ."},{"p":"Dạng phủ định đã chọn đúng giữa nghĩa cấm và nghĩa không cần."},{"p":"Ought to là khuyết thiếu duy nhất trong bài giữ chữ to: ought to be, không phải ought be."}]}],"id":"a2-07"},{"n":8,"title":"-ed and -ing adjectives","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhiều tính từ tiếng Anh có hai dạng xuất phát từ cùng một động từ và chúng không thay thế nhau được. Dạng -ing cho biết nguyên nhân: sự vật hoặc tình huống nào gây ra cảm giác. Dạng -ed cho biết kết quả: người nào mang cảm giác đó. Nhầm hai dạng này tạo ra những câu rất buồn cười, ví dụ I am boring nghĩa là tôi là người nhàm chán."},{"p":"Cấu trúc chính: sự vật + -ing | người + -ed"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The film was boring, so we were bored. (Miêu tả nguyên nhân gây ra cảm giác | Miêu tả cảm giác của người | Bổ nghĩa trực tiếp cho danh từ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Miêu tả nguyên nhân gây ra cảm giác: Dùng dạng -ing cho phim, sách, công việc, tin tức, chuyến đi. (The news was shocking.)"},{"p":"Miêu tả cảm giác của người: Dùng dạng -ed cho người và thường đi với động từ to be hoặc feel. (I felt shocked.)"},{"p":"Bổ nghĩa trực tiếp cho danh từ: Cả hai dạng đều đứng được trước danh từ, nhưng nghĩa khác nhau. (an interesting book ↔ an interested reader)"},{"p":"Kết hợp với giới từ: Dạng -ed thường đi với một giới từ cố định. (interested in / worried about / surprised at)"},{"p":"Ghi nhớ: Tính từ đuôi -ing miêu tả sự vật gây ra cảm giác, tính từ đuôi -ed miêu tả người có cảm giác đó."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: sự vật + -ing | người + -ed"},{"table":[["Dạng thức","Đối tượng / Quy tắc","Ví dụ"],["Dạng -ing","sự vật, tình huống gây ra cảm giác","boring, interesting, tiring, surprising, worrying"],["Dạng -ed","người mang cảm giác","bored, interested, tired, surprised, worried"],["Trước danh từ","cả hai dạng, nhưng nghĩa khác nhau","a tiring journey ↔ a tired traveller"],["Giới từ đi kèm","interested in, bored with, worried about, excited about, surprised at","She is interested in history."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Phân biệt nguyên nhân và người cảm nhận: Nguyên nhân thì dùng -ing, người cảm nhận thì dùng -ed. (The job is tiring. ↔ I am tired.)"},{"p":"02. Kiểm tra chủ ngữ là người hay vật: Vật và tình huống hầu như luôn đi với -ing; người thường đi với -ed. (The lesson was confusing. / The students were confused.)"},{"p":"03. Nhớ giới từ đi kèm dạng -ed: Mỗi tính từ -ed có một giới từ cố định phải học cùng. (worried about the exam)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Cả hai dạng trong một câu","The film was boring, so we were bored.\n(Bộ phim nhàm chán nên chúng tôi thấy buồn.)","Phim là nguyên nhân nên dùng boring; chúng tôi là người cảm nhận nên dùng bored."],["Nguyên nhân","The journey was very tiring.\n(Chuyến đi rất mệt.)","Chuyến đi gây ra sự mệt mỏi nên dùng dạng -ing."],["Người cảm nhận","After the journey we were all tired.\n(Sau chuyến đi, tất cả chúng tôi đều mệt.)","Chúng tôi là người mang cảm giác nên dùng dạng -ed."],["Bổ nghĩa cho danh từ","It was an interesting lecture, and there were many interested students.\n(Đó là một bài giảng hay và có nhiều sinh viên quan tâm.)","Bài giảng gây ra sự quan tâm nên dùng interesting; sinh viên mang cảm giác nên dùng interested."],["Với giới từ","She is really interested in Vietnamese history.\n(Cô ấy rất quan tâm đến lịch sử Việt Nam.)","Interested luôn đi với giới từ in."],["Tình huống gây lo","The test results were worrying, so the parents were worried about them.\n(Kết quả kiểm tra đáng lo, nên phụ huynh lo lắng về chúng.)","Kết quả gây lo nên dùng worrying; phụ huynh mang cảm giác nên dùng worried about."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Cặp tính từ thường dùng"},{"table":[["Cặp tính từ","Nghĩa","Ví dụ"],["boring / bored","gây nhàm chán / thấy buồn","a boring lesson — a bored student"],["exciting / excited","gây háo hức / thấy háo hức","an exciting match — excited fans"],["confusing / confused","gây rối / thấy rối","confusing instructions — a confused reader"],["surprising / surprised","gây bất ngờ / thấy bất ngờ","surprising news — surprised listeners"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The film was bored, so we were boring. → Đã sửa: The film was boring, so we were bored. — Hai dạng bị đảo chỗ, làm câu mang nghĩa phim thấy buồn và chúng tôi là người nhàm chán."},{"p":"Chưa đúng: I am very interesting in music. → Đã sửa: I am very interested in music. — Người mang cảm giác dùng dạng -ed và interested đi với giới từ in."},{"p":"Chưa đúng: She was surprised of the news. → Đã sửa: She was surprised at the news. — Surprised đi với giới từ at hoặc by, không đi với of."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Câu nói về nguyên nhân hay về người cảm nhận."},{"p":"Chủ ngữ là người thì thường đi với dạng -ed."},{"p":"Dạng -ing dùng cho sự vật và tình huống."},{"p":"Giới từ đi kèm tính từ -ed đã đúng."}]}],"id":"a2-08"},{"n":9,"title":"Adjective order","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Tiếng Anh có một trật tự gần như cố định cho nhiều tính từ đứng trước cùng một danh từ. Người bản ngữ không học quy tắc này nhưng nghe ra ngay khi bị đảo. Quy luật chung là tính từ nêu ý kiến chủ quan đứng xa danh từ nhất, còn tính từ nêu đặc điểm khách quan và gắn chặt với bản chất của vật thì đứng gần danh từ nhất."},{"p":"Cấu trúc chính: ý kiến + kích thước + tuổi + hình dạng + màu sắc + xuất xứ + chất liệu + danh từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She bought a beautiful small old wooden box. (Hai tính từ bổ nghĩa một danh từ | Miêu tả đồ vật chi tiết | Miêu tả người)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Hai tính từ bổ nghĩa một danh từ: Trường hợp thông dụng nhất và chỉ cần nhớ loại nào đứng trước. (a big red bus)"},{"p":"Miêu tả đồ vật chi tiết: Thường gặp khi giới thiệu sản phẩm hoặc miêu tả đồ đạc. (a lovely little Italian restaurant)"},{"p":"Miêu tả người: Ý kiến đứng trước, rồi tuổi, rồi đặc điểm ngoại hình. (a friendly young English teacher)"},{"p":"Dùng dấu phẩy khi các tính từ cùng loại: Khi hai tính từ cùng nêu ý kiến, dùng dấu phẩy hoặc and. (a cold, wet morning)"},{"p":"Ghi nhớ: Khi nhiều tính từ cùng bổ nghĩa một danh từ, chúng xếp theo thứ tự ý kiến, kích thước, tuổi, màu sắc, xuất xứ, chất liệu."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: ý kiến + kích thước + tuổi + hình dạng + màu sắc + xuất xứ + chất liệu + danh từ"},{"table":[["Nhóm tính từ","Thứ tự / Từ vựng","Ví dụ"],["Thứ tự chuẩn","ý kiến → kích thước → tuổi → hình dạng → màu sắc → xuất xứ → chất liệu → mục đích","a nice big new round black Italian leather sofa"],["Ý kiến","beautiful, lovely, terrible, interesting","a beautiful painting"],["Đặc điểm khách quan","small, old, square, blue, Japanese, plastic","a small blue plastic bottle"],["Cùng loại","tính từ, tính từ hoặc tính từ and tính từ","a dark, narrow street"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Tách tính từ ý kiến ra trước: Ý kiến đứng trước mọi loại còn lại. (a beautiful old house)"},{"p":"02. Xếp tính từ khách quan theo quy ước: Kích thước trước tuổi, tuổi trước màu sắc, màu sắc trước xuất xứ, xuất xứ trước chất liệu. (a small old brown leather bag)"},{"p":"03. Hạn chế số tính từ trong một cụm: Trong thực tế hiếm khi dùng quá ba tính từ liền nhau; nhiều hơn thì nên tách thành mệnh đề. (a small wooden box that my grandfather made)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Thứ tự nhiều tính từ","She bought a beautiful small old wooden box.\n(Cô ấy mua một cái hộp gỗ nhỏ cũ rất đẹp.)","Ý kiến beautiful, kích thước small, tuổi old, chất liệu wooden; chất liệu đứng sát danh từ nhất."],["Hai tính từ","A big red bus stopped in front of the school.\n(Một chiếc xe buýt đỏ to dừng trước cổng trường.)","Kích thước big đứng trước màu sắc red."],["Miêu tả nhà hàng","We found a lovely little Italian restaurant near the river.\n(Chúng tôi tìm được một nhà hàng Ý nhỏ xinh gần bờ sông.)","Ý kiến lovely, kích thước little, xuất xứ Italian."],["Miêu tả người","Our new teacher is a friendly young Englishman.\n(Thầy mới của chúng tôi là một người Anh trẻ và thân thiện.)","Ý kiến friendly đứng trước tuổi young."],["Tính từ cùng loại","It was a cold, wet morning in January.\n(Đó là một buổi sáng tháng Một lạnh và ẩm.)","Cold và wet cùng nêu đặc điểm thời tiết nên tách bằng dấu phẩy."],["Chất liệu sát danh từ","He wore an expensive black leather jacket.\n(Anh ấy mặc một chiếc áo khoác da đen đắt tiền.)","Ý kiến expensive, màu sắc black, chất liệu leather; chất liệu luôn ở sát danh từ."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Thứ tự theo mức độ khách quan"},{"table":[["Nhóm tính từ","Vị trí","Ví dụ"],["ý kiến","xa danh từ nhất","beautiful, awful, interesting"],["kích thước và tuổi","ở giữa","big, small, old, new"],["màu sắc và xuất xứ","gần danh từ hơn","red, blue, Japanese, French"],["chất liệu và mục đích","sát danh từ nhất","wooden, leather, running (shoes)"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She bought a wooden old small beautiful box. → Đã sửa: She bought a beautiful small old wooden box. — Trật tự bị đảo hoàn toàn: ý kiến phải đứng đầu, chất liệu phải sát danh từ."},{"p":"Chưa đúng: a red big bus → Đã sửa: a big red bus — Kích thước đứng trước màu sắc."},{"p":"Chưa đúng: a leather black expensive jacket → Đã sửa: an expensive black leather jacket — Ý kiến đứng xa danh từ nhất, chất liệu đứng gần danh từ nhất."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Tính từ nêu ý kiến đứng trước các tính từ còn lại."},{"p":"Chất liệu và mục đích đứng sát danh từ."},{"p":"Các tính từ cùng loại được tách bằng dấu phẩy hoặc and."},{"p":"Cụm không có quá nhiều tính từ liền nhau."}]}],"id":"a2-09"},{"n":10,"title":"Comparatives","sections":[{"h":"TRỌNG TÂM","items":[{"p":"So sánh hơn đặt hai đối tượng cạnh nhau để chỉ ra đối tượng nào có đặc điểm ở mức cao hơn. Hình thức phụ thuộc vào độ dài của tính từ: một âm tiết thêm -er, từ ba âm tiết trở lên dùng more và nhóm hai âm tiết chia theo đuôi từ. Từ nối giữa hai vế luôn là than."},{"p":"Cấu trúc chính: adj-er / more + adj + than"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): This book is more interesting than that one. (So sánh hai người, hai vật | So sánh hai thời điểm hoặc hai tình trạng | Nhấn mạnh mức độ chênh lệch)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"So sánh hai người, hai vật: Cả hai đối tượng được nêu rõ, nối bằng than. (My bag is heavier than yours.)"},{"p":"So sánh hai thời điểm hoặc hai tình trạng: Dùng để chỉ sự thay đổi theo thời gian. (Today is colder than yesterday.)"},{"p":"Nhấn mạnh mức độ chênh lệch: Thêm much, far, a bit, slightly trước dạng so sánh hơn. (This is much cheaper than that.)"},{"p":"So sánh bằng và so sánh kém: As … as diễn tả mức ngang nhau, less … than diễn tả mức thấp hơn. (She is as tall as her brother.)"},{"p":"Ghi nhớ: Tính từ ngắn thêm -er, tính từ dài dùng more và vế sau nối bằng than."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: adj-er / more + adj + than"},{"table":[["Loại tính từ","Công thức / Quy tắc","Ví dụ"],["Một âm tiết","adj + -er","tall → taller, cheap → cheaper"],["Chính tả đặc biệt","nhân đôi phụ âm cuối | phụ âm + y → -ier","big → bigger, happy → happier"],["Ba âm tiết trở lên","more + adj","interesting → more interesting"],["Bất quy tắc","good → better, bad → worse, far → farther/further","This is better than that."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Đếm số âm tiết của tính từ: Một âm tiết dùng -er; ba âm tiết trở lên dùng more; hai âm tiết thì tuỳ đuôi từ, các từ kết thúc bằng -y, -er, -ow thường thêm -er. (narrow → narrower / modern → more modern)"},{"p":"02. Áp quy tắc chính tả: Tính từ một âm tiết kết thúc bằng nguyên âm + phụ âm thì nhân đôi phụ âm cuối; phụ âm + y đổi thành -ier. (hot → hotter / easy → easier)"},{"p":"03. Nối hai vế bằng than: Than là liên từ so sánh duy nhất ở cấu trúc này; dùng that hoặc then đều sai. (cheaper than this one)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Tính từ dài","This book is more interesting than that one.\n(Quyển sách này hay hơn quyển kia.)","Interesting có bốn âm tiết nên dùng more; vế sau nối bằng than."],["Tính từ ngắn","The red bag is cheaper than the blue one.\n(Cái túi đỏ rẻ hơn cái túi xanh.)","Cheap có một âm tiết nên thêm -er."],["Nhân đôi phụ âm","Today is hotter than yesterday.\n(Hôm nay nóng hơn hôm qua.)","Hot có một âm tiết, kết thúc bằng nguyên âm + phụ âm nên nhân đôi t."],["Bất quy tắc","Her English is better than mine, but her French is worse.\n(Tiếng Anh của cô ấy tốt hơn tôi, nhưng tiếng Pháp thì kém hơn.)","Good → better và bad → worse không theo quy tắc nào."],["Nhấn mạnh chênh lệch","This phone is much more expensive than the old model.\n(Chiếc điện thoại này đắt hơn nhiều so với mẫu cũ.)","Much đứng trước dạng so sánh hơn để nhấn mạnh khoảng cách lớn."],["So sánh bằng","She is as tall as her brother.\n(Cô ấy cao bằng anh trai.)","As … as diễn tả mức ngang nhau; giữa hai as là tính từ ở dạng nguyên."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Ba mức so sánh giữa hai đối tượng"},{"table":[["Cấu trúc","Mức độ","Ví dụ"],["more/-er … than","hơn","A is bigger than B."],["as … as","bằng","A is as big as B."],["not as … as / less … than","kém hơn","B is not as big as A."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: This book is more interesting that that one. → Đã sửa: This book is more interesting than that one. — Từ nối trong so sánh hơn là than, không phải that."},{"p":"Chưa đúng: She is more taller than me. → Đã sửa: She is taller than me. — Không dùng đồng thời more và đuôi -er trên cùng một tính từ."},{"p":"Chưa đúng: This exercise is more easy than that one. → Đã sửa: This exercise is easier than that one. — Easy là tính từ hai âm tiết kết thúc bằng -y nên thêm -ier."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Tính từ có mấy âm tiết."},{"p":"Dạng so sánh dùng -er hay more, không dùng cả hai."},{"p":"Chính tả khi nhân đôi phụ âm hoặc đổi -y thành -i."},{"p":"Hai vế nối bằng than."}]}],"id":"a2-10"},{"n":11,"title":"Superlatives","sections":[{"h":"TRỌNG TÂM","items":[{"p":"So sánh nhất xếp một đối tượng ở vị trí cao nhất hoặc thấp nhất trong một nhóm từ ba thành viên trở lên. Dấu hiệu hình thức gồm hai phần không thể thiếu: mạo từ the và đuôi -est hoặc từ most. Phạm vi so sánh thường được nêu bằng in, of hoặc một mệnh đề quan hệ."},{"p":"Cấu trúc chính: the + adj-est | the most + adj"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): She is the best student in our class. (Xếp hạng trong một nhóm | Nhấn mạnh kỉ lục hoặc trải nghiệm đỉnh điểm | Chỉ mức thấp nhất)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Xếp hạng trong một nhóm: Phạm vi nhóm được nêu bằng in với địa điểm, tổ chức hoặc of với tập hợp. (the tallest building in Hanoi)"},{"p":"Nhấn mạnh kỉ lục hoặc trải nghiệm đỉnh điểm: Thường kết hợp với hiện tại hoàn thành và ever. (It's the best film I have ever seen.)"},{"p":"Chỉ mức thấp nhất: Dùng the least với tính từ dài hoặc dạng bất quy tắc the worst. (the least expensive option)"},{"p":"Xếp thứ tự thứ hai, thứ ba: Thêm số thứ tự trước dạng so sánh nhất. (the second largest city)"},{"p":"Ghi nhớ: Tính từ ngắn thêm -est, tính từ dài dùng most và thường có mạo từ the trước danh từ."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: the + adj-est | the most + adj"},{"table":[["Loại tính từ","Công thức / Quy tắc","Ví dụ"],["Một âm tiết","the + adj + -est","tall → the tallest"],["Chính tả đặc biệt","nhân đôi phụ âm cuối | phụ âm + y → -iest","big → the biggest, busy → the busiest"],["Ba âm tiết trở lên","the most + adj","the most beautiful"],["Bất quy tắc","good → the best, bad → the worst, far → the farthest","the best student"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác nhận nhóm có từ ba đối tượng: Chỉ có hai đối tượng thì phải dùng so sánh hơn, không dùng so sánh nhất. (the taller of the two)"},{"p":"02. Thêm mạo từ the trước dạng so sánh nhất: Thường dùng the trước tính từ so sánh nhất bổ nghĩa cho danh từ (the tallest student); không dùng the khi đã có từ sở hữu (my biggest mistake) và có thể lược the ở một số cách dùng vị ngữ/trạng ngữ không có danh từ theo sau (Which is best? / Who runs fastest?)."},{"p":"03. Nêu phạm vi so sánh: Dùng in với nơi hoặc tổ chức, of với tập hợp người hoặc vật. (the best in the class / the oldest of the three)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Bất quy tắc","She is the best student in our class.\n(Cô ấy là học sinh giỏi nhất lớp.)","Good → the best; mạo từ the là thành phần bắt buộc và phạm vi nêu bằng in."],["Tính từ ngắn","This is the tallest building in the city.\n(Đây là toà nhà cao nhất thành phố.)","Tall có một âm tiết nên thêm -est."],["Phụ âm + y","Monday is the busiest day of the week.\n(Thứ Hai là ngày bận nhất trong tuần.)","Busy đổi y thành i rồi thêm -est; phạm vi nêu bằng of."],["Tính từ dài","Ha Long Bay is one of the most beautiful places in Vietnam.\n(Vịnh Hạ Long là một trong những nơi đẹp nhất Việt Nam.)","Beautiful có ba âm tiết nên dùng the most; cụm one of the most đi với danh từ số nhiều."],["Kết hợp với ever","That was the worst meal I have ever eaten.\n(Đó là bữa ăn tệ nhất tôi từng ăn.)","So sánh nhất rất hay đi với mệnh đề quan hệ có hiện tại hoàn thành và ever."],["Số thứ tự","Da Nang is the third largest city in Vietnam.\n(Đà Nẵng là thành phố lớn thứ ba Việt Nam.)","Số thứ tự đứng giữa the và dạng so sánh nhất."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: So sánh hơn và so sánh nhất"},{"table":[["Cấu trúc","Phạm vi dùng","Ví dụ"],["so sánh hơn","hai đối tượng, nối bằng than","A is bigger than B."],["so sánh nhất","ba đối tượng trở lên, có the và nêu phạm vi","A is the biggest in the group."],["one of the + so sánh nhất","một trong những, danh từ ở số nhiều","one of the oldest temples"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: She is best student in our class. → Đã sửa: She is the best student in our class. — Tính từ so sánh nhất bổ nghĩa cho danh từ thường cần mạo từ the (trừ khi có từ sở hữu đứng trước)."},{"p":"Chưa đúng: This is the most tallest building. → Đã sửa: This is the tallest building. — Không dùng đồng thời most và đuôi -est."},{"p":"Chưa đúng: He is the oldest of the two brothers. → Đã sửa: He is the older of the two brothers. — Chỉ có hai đối tượng thì dùng so sánh hơn, không dùng so sánh nhất."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Nhóm so sánh có từ ba đối tượng trở lên."},{"p":"Có mạo từ the trước dạng so sánh nhất."},{"p":"Dùng -est hoặc most, không dùng cả hai."},{"p":"Phạm vi so sánh nêu bằng in hoặc of cho phù hợp."}]}],"id":"a2-11"},{"n":12,"title":"Too & enough","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Hai cấu trúc này nêu quan hệ giữa một mức độ và một kết quả. Too báo rằng mức độ vượt quá giới hạn nên kết quả không xảy ra được; enough báo rằng mức độ đạt yêu cầu nên kết quả xảy ra được. Điểm hình thức dễ sai là vị trí của enough, vì từ này đứng sau tính từ nhưng đứng trước danh từ."},{"p":"Cấu trúc chính: too + tính từ + to-V | tính từ + enough + to-V | enough + danh từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): The box was too heavy to carry, but I was strong enough to move it. (Nêu mức quá giới hạn | Nêu mức vừa đủ | Nêu số lượng đủ hoặc không đủ)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nêu mức quá giới hạn: Too cộng tính từ, rồi to-V nêu việc không làm được. (It's too dark to read.)"},{"p":"Nêu mức vừa đủ: Tính từ cộng enough, rồi to-V nêu việc làm được. (She is old enough to vote.)"},{"p":"Nêu số lượng đủ hoặc không đủ: Enough đứng trước danh từ; dạng phủ định là not enough. (We have enough chairs. / There isn't enough time.)"},{"p":"Nêu người thực hiện: Thêm for + người trước to-V khi cần làm rõ ai thực hiện. (The soup is too hot for the children to eat.)"},{"p":"Ghi nhớ: Too mang nghĩa quá mức nên không làm được; enough mang nghĩa đủ để làm được."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: too + tính từ + to-V | tính từ + enough + to-V | enough + danh từ"},{"table":[["Cấu trúc","Công thức","Ví dụ"],["too + tính từ","too + tính từ (+ for + người) + to-V","too expensive for us to buy"],["tính từ + enough","tính từ + enough (+ for + người) + to-V","warm enough to swim"],["enough + danh từ","enough + danh từ + to-V","enough money to travel"],["too much / too many","too much + danh từ không đếm được | too many + danh từ số nhiều","too much salt, too many people"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định mức độ là quá hay vừa đủ: Quá mức thì dùng too, đạt yêu cầu thì dùng enough. (too small ↔ big enough)"},{"p":"02. Đặt enough đúng vị trí: Sau tính từ và trạng từ, nhưng trước danh từ. (strong enough / enough strength)"},{"p":"03. Dùng to-V cho phần kết quả: Phần nêu việc làm được hay không làm được luôn ở dạng to-V. (too heavy to carry, không phải for carry)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Cả hai cấu trúc trong một câu","The box was too heavy to carry, but I was strong enough to move it.\n(Cái hộp quá nặng không bê được, nhưng tôi đủ sức để đẩy nó.)","Too đứng trước tính từ, enough đứng sau tính từ; cả hai đều đi với to-V."],["Quá mức","It's too dark to read in here.\n(Trong này quá tối, không đọc được.)","Too dark báo rằng mức tối vượt giới hạn nên việc đọc không thực hiện được."],["Vừa đủ","She is old enough to vote in the next election.\n(Cô ấy đã đủ tuổi để bầu cử ở kì tới.)","Enough đứng ngay sau tính từ old."],["Enough với danh từ","We don't have enough chairs for everyone.\n(Chúng ta không có đủ ghế cho mọi người.)","Trước danh từ, enough đứng ở phía trước chứ không phải phía sau."],["Nêu người thực hiện","The soup is too hot for the children to eat.\n(Món canh quá nóng, các em không ăn được.)","Cụm for the children làm rõ ai là người không thực hiện được việc đó."],["Too much và too many","There was too much salt in the soup and too many people in the kitchen.\n(Canh quá mặn và trong bếp quá nhiều người.)","Too much đi với danh từ không đếm được, too many đi với danh từ đếm được số nhiều."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Vị trí của enough và nghĩa của too"},{"table":[["Cấu trúc","Nghĩa","Ví dụ"],["tính từ + enough","đủ để làm được","tall enough to reach it"],["enough + danh từ","đủ số lượng","enough chairs for everyone"],["too + tính từ","quá mức nên không làm được","too short to reach it"],["very + tính từ","chỉ nhấn mức độ, không hàm ý kết quả","very tall (không nói gì về việc với tới)"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: The box was too heavy for carry it. → Đã sửa: The box was too heavy to carry. — Phần kết quả dùng to-V và không lặp lại tân ngữ it."},{"p":"Chưa đúng: She is enough old to vote. → Đã sửa: She is old enough to vote. — Enough đứng sau tính từ, không đứng trước."},{"p":"Chưa đúng: We don't have chairs enough. → Đã sửa: We don't have enough chairs. — Trước danh từ, enough đứng ở phía trước."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Mức độ là quá giới hạn hay vừa đủ."},{"p":"Enough đứng sau tính từ nhưng trước danh từ."},{"p":"Phần kết quả ở dạng to-V."},{"p":"Không lặp lại tân ngữ sau to-V."}]}],"id":"a2-12"},{"n":13,"title":"So & such","sections":[{"h":"TRỌNG TÂM","items":[{"p":"So và such cùng nhấn mạnh mức độ, nhưng khác nhau ở thành phần đi sau. So đứng trước một tính từ hoặc trạng từ đứng trơ. Such đứng trước một cụm danh từ, và nếu danh từ đếm được số ít thì phải có mạo từ a hoặc an. Cả hai kết hợp được với that cộng mệnh đề để nêu kết quả."},{"p":"Cấu trúc chính: so + tính từ (+ that + mệnh đề) | such + (a/an) + tính từ + danh từ"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): It was such a cold night that we stayed indoors. (Nhấn mạnh tính từ hoặc trạng từ | Nhấn mạnh một cụm danh từ | Nêu kết quả)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nhấn mạnh tính từ hoặc trạng từ: So đứng trước tính từ hoặc trạng từ không có danh từ theo sau. (The film was so long.)"},{"p":"Nhấn mạnh một cụm danh từ: Such đứng trước cụm danh từ, giữ nguyên mạo từ nếu có. (It was such a long film.)"},{"p":"Nêu kết quả: Thêm that cộng mệnh đề để cho biết mức độ đó dẫn tới điều gì. (He spoke so quietly that nobody heard him.)"},{"p":"Nhấn mạnh số lượng: So đi với many, much, few, little trước danh từ. (There were so many people that we left.)"},{"p":"Ghi nhớ: So đi với tính từ hoặc trạng từ, such đi với một cụm danh từ; cả hai nhấn mạnh mức độ và dẫn tới kết quả."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: so + tính từ (+ that + mệnh đề) | such + (a/an) + tính từ + danh từ"},{"table":[["Dạng thức","Công thức","Ví dụ"],["so + tính từ hoặc trạng từ","so + adj/adv (+ that + mệnh đề)","so tired that she fell asleep"],["such + cụm danh từ","such + (a/an) + (adj) + danh từ (+ that + mệnh đề)","such a kind woman"],["so với lượng từ","so many/much/few/little + danh từ","so much noise"],["Không có mệnh đề kết quả","chỉ nhấn mạnh, bỏ phần that","Thank you — you're so kind!"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xét thành phần đứng sau: Có danh từ thì dùng such; không có danh từ thì dùng so. (so cold ↔ such a cold night)"},{"p":"02. Giữ mạo từ trong cụm danh từ sau such: Danh từ đếm được số ít cần a hoặc an; số nhiều và không đếm được thì không cần. (such a good idea / such good news)"},{"p":"03. Thêm that khi cần nêu kết quả: Mệnh đề sau that là một câu hoàn chỉnh có chủ ngữ và động từ. (so hot that the road melted)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Such với cụm danh từ","It was such a cold night that we stayed indoors.\n(Đêm đó lạnh đến mức chúng tôi ở trong nhà.)","Sau such là cụm danh từ a cold night, nên mạo từ a được giữ nguyên."],["So với tính từ","The night was so cold that we stayed indoors.\n(Đêm đó lạnh đến mức chúng tôi ở trong nhà.)","Cùng nội dung nhưng ở đây cold đứng trơ, không có danh từ theo sau, nên dùng so."],["So với trạng từ","He spoke so quietly that nobody could hear him.\n(Anh ấy nói nhỏ đến mức không ai nghe được.)","So cũng dùng được trước trạng từ chỉ cách thức."],["So với lượng từ","There were so many people at the market that we decided to leave.\n(Chợ đông đến mức chúng tôi quyết định về.)","Khi có many, much, few, little thì dùng so dù phía sau có danh từ."],["Such với danh từ không đếm được","That was such good news!\n(Đó là một tin tốt quá!)","News không đếm được nên không có mạo từ sau such."],["Chỉ nhấn mạnh","Thank you for helping — you are so kind.\n(Cảm ơn bạn đã giúp, bạn tốt quá.)","Không nhất thiết phải có mệnh đề kết quả; so vẫn dùng để nhấn mạnh."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Chọn so hay such"},{"table":[["Cấu trúc","Điều kiện","Ví dụ"],["so + tính từ","không có danh từ theo sau","so expensive"],["such + a/an + tính từ + danh từ","danh từ đếm được số ít","such an expensive car"],["such + tính từ + danh từ","danh từ số nhiều hoặc không đếm được","such expensive cars, such bad weather"],["so + many/much","nhấn mạnh số lượng","so many cars, so much traffic"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: It was so a cold night that we stayed indoors. → Đã sửa: It was such a cold night that we stayed indoors. — Có cụm danh từ a cold night nên phải dùng such."},{"p":"Chưa đúng: She is such tired that she went to bed. → Đã sửa: She is so tired that she went to bed. — Tired đứng trơ, không có danh từ theo sau, nên dùng so."},{"p":"Chưa đúng: There were such many people that we left. → Đã sửa: There were so many people that we left. — Khi có lượng từ many thì dùng so, không dùng such."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Sau vị trí cần điền có danh từ hay không."},{"p":"Mạo từ trong cụm danh từ sau such được giữ đúng."},{"p":"Lượng từ many và much đi với so, không đi với such."},{"p":"Mệnh đề sau that là một câu hoàn chỉnh."}]}],"id":"a2-13"},{"n":14,"title":"And, but, or, so & because","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Liên từ cho biết quan hệ logic giữa hai ý. And thêm ý, but nêu tương phản, or nêu lựa chọn, so dẫn tới kết quả, còn because nêu nguyên nhân. So và because là cặp dễ lẫn nhất vì chúng biểu đạt cùng một quan hệ nhân quả nhưng theo hai chiều ngược nhau."},{"p":"Cấu trúc chính: mệnh đề + liên từ + mệnh đề"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): It was raining, so we stayed at home. (Thêm thông tin cùng hướng | Nêu tương phản | Nêu lựa chọn)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Thêm thông tin cùng hướng: And nối hai ý tương đồng, có thể nối từ, cụm từ hoặc cả mệnh đề. (She sings and plays the piano.)"},{"p":"Nêu tương phản: But đặt hai ý trái chiều cạnh nhau. (It was cheap but very good.)"},{"p":"Nêu lựa chọn: Or đưa ra các khả năng thay thế nhau. (We can walk or take a bus.)"},{"p":"Nêu nguyên nhân và kết quả: Because dẫn vào nguyên nhân, so dẫn vào kết quả. (We stayed in because it rained. ↔ It rained, so we stayed in.)"},{"p":"Nguyên nhân: because, as, since và because of: Because, as và since cùng mở mệnh đề nguyên nhân; because thông dụng nhất, as và since trang trọng hơn và hay đứng đầu câu. Riêng because of không đi với mệnh đề: sau nó là một cụm danh từ. (We stayed at home because/as/since it was raining. / The survey was postponed because of the typhoon.)"},{"p":"Tương phản mạnh hơn but: yet, although, though: Yet thay được but với sắc thái trang trọng. Although, though và even though mở mệnh đề nhượng bộ - đặt được ở đầu câu, điều but không làm được; even though nhấn mạnh nhất. While đặt hai vế cạnh nhau để đối chiếu. (I called her, yet she didn't answer. /Although the sample was small, the effect was clear. / While A is cheap, B is precise.)"},{"p":"So nêu kết quả, so that nêu mục đích: So trả lời câu hỏi chuyện gì xảy ra tiếp theo; so that trả lời câu hỏi làm việc đó để làm gì. Hai nghĩa khác hẳn nhau dù chỉ chênh một chữ. (The sample was contaminated, so the run was repeated. / Readings are taken at dawn so that the air is still.)"},{"p":"Ghi nhớ: Nối hai mệnh đề theo quan hệ thêm ý, tương phản, lựa chọn, kết quả hoặc nguyên nhân."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: mệnh đề + liên từ + mệnh đề"},{"table":[["Liên từ","Công thức / Ý nghĩa","Ví dụ"],["and","ý thêm vào","He washed the dishes and cleaned the floor."],["but","ý tương phản","I called her, but she didn't answer."],["or","ý lựa chọn","Tea or coffee?"],["so / because","mệnh đề + so + kết quả | mệnh đề + because + nguyên nhân","I was tired, so I went to bed because I had to get up early."],["because · as · since","mệnh đề + because/as/since + mệnh đề nguyên nhân (as, since trang trọng hơn)","He was absent because he had a fever. / Since it was late, we left."],["because of + danh từ","because of + cụm danh từ (không có chủ ngữ - động từ theo sau)","The survey was postponed because of the typhoon."],["although · though · even though","Although/Though/Even though + mệnh đề, + mệnh đề chính | mệnh đề chính + although + mệnh đề","Although the sample was small, the effect was unmistakable."],["so · so that","mệnh đề + so + kết quả | mệnh đề + so that + mục đích","It rained, so we stayed in. / Note everything so that nothing is lost."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định quan hệ giữa hai ý: Hỏi xem ý sau là ý thêm vào, ý trái chiều, ý lựa chọn, kết quả hay nguyên nhân. (trời mưa → ở nhà: quan hệ nhân quả)"},{"p":"02. Chọn chiều của quan hệ nhân quả: Nếu mệnh đề sau là nguyên nhân thì dùng because; nếu là kết quả thì dùng so. (…, so we stayed at home.)"},{"p":"03. Kiểm tra chủ ngữ và động từ: Liên từ nối hai mệnh đề hoàn chỉnh; dấu phẩy thường đặt trước but và so. (It was raining, so we stayed at home.)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Kết quả","It was raining, so we stayed at home.\n(Trời mưa nên chúng tôi ở nhà.)","Mệnh đề sau là kết quả của mệnh đề trước, vì vậy dùng so."],["Nguyên nhân","We stayed at home because it was raining.\n(Chúng tôi ở nhà vì trời mưa.)","Cùng một nội dung nhưng trật tự đảo lại, nên liên từ đổi thành because."],["Tương phản","The hotel was cheap but very comfortable.\n(Khách sạn rẻ mà rất thoải mái.)","But nối hai tính từ trái chiều mà không cần lặp lại chủ ngữ."],["Thêm ý","She finished her homework and went out with her friends.\n(Cô ấy làm xong bài tập rồi đi chơi với bạn.)","And nối hai hành động cùng chủ ngữ nên chủ ngữ thứ hai được lược bỏ."],["Lựa chọn","We can walk to the station or take a taxi.\n(Chúng ta có thể đi bộ đến ga hoặc bắt taxi.)","Or đưa ra hai khả năng thay thế nhau."],["Nhiều liên từ trong một câu","I wanted to call her, but I had no signal, so I sent a message instead.\n(Tôi muốn gọi cho cô ấy nhưng không có tín hiệu, nên tôi nhắn tin.)","Ba mệnh đề nối bằng but rồi so, mỗi liên từ thể hiện một quan hệ riêng."],["Nhượng bộ","Although the sample was small, the effect was unmistakable.\n(Tuy mẫu nhỏ, hiệu ứng vẫn rõ rành rành.)","Although mở mệnh đề nhượng bộ ở đầu câu\n- chỗ này không thay bằng but được vì but chỉ đứng giữa hai vế. Though và even though dùng y hệt, even though nhấn mạnh hơn."],["Mục đích","Readings are taken at dawn so that the wind cannot affect them.\n(Số liệu được đo lúc rạng sáng để gió không làm sai lệch kết quả.)","So that nêu mục đích của việc đo; nếu dùng so trơn thì câu lại thành kết quả - nghĩa đổi hẳn."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: So và because nhìn từ hai chiều"},{"table":[["Cấu trúc","Quan hệ / Phân biệt","Ví dụ"],["A, so B","A là nguyên nhân, B là kết quả","I was hungry, so I ate."],["B because A","B là kết quả, A là nguyên nhân","I ate because I was hungry."],["Because A, B","đảo mệnh đề nguyên nhân lên trước, thêm dấu phẩy","Because I was hungry, I ate."],["because ≠ because of","because + mệnh đề; because of + cụm danh từ","because it rained ≠ because of the rain"],["but ≈ yet ≠ although","but/yet nối giữa câu; although mở mệnh đề nhượng bộ, đứng được đầu câu","small but clear / Although small, it was clear."],["so ≠ so that","so = vì thế (kết quả); so that = để mà (mục đích)","…, so we left. / … so that we could leave early."],["as / since","nghĩa nguyên nhân như because, trang trọng hơn, hay đứng đầu câu","Since the data are public, anyone can check."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: It was raining, because we stayed at home. → Đã sửa: It was raining, so we stayed at home. — Mệnh đề sau là kết quả nên phải dùng so, không dùng because."},{"p":"Chưa đúng: Because it was raining, so we stayed at home. → Đã sửa: Because it was raining, we stayed at home. — Trong một câu chỉ dùng một liên từ cho một quan hệ, không dùng cả because và so."},{"p":"Chưa đúng: She is tired but she worked all night and. → Đã sửa: She is tired because she worked all night. — Liên từ không đứng cuối câu và quan hệ ở đây là nguyên nhân."},{"p":"Chưa đúng: Because of it was raining, we stayed at home. → Đã sửa: Because it was raining, we stayed at home. — Sau because of chỉ được đặt cụm danh từ; có chủ ngữ - động từ theo sau thì dùng because."},{"p":"Chưa đúng: Although it rained, but we still went out. → Đã sửa: Although it rained, we still went out. — Although đã nêu nhượng bộ rồi, thêm but là thừa một liên từ - tiếng Anh chỉ cần một."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Quan hệ giữa hai ý là thêm, tương phản, lựa chọn hay nhân quả."},{"p":"Chiều của quan hệ nhân quả đã chọn đúng liên từ."},{"p":"Mỗi mệnh đề có đủ chủ ngữ và động từ."},{"p":"Không dùng hai liên từ cho cùng một quan hệ trong một câu."},{"p":"Sau because of phải là cụm danh từ; sau because/as/since là mệnh đề đủ chủ ngữ - động từ."},{"p":"Nhượng bộ đứng đầu câu dùng although/though/even though, không dùng but."},{"p":"Phân biệt so (kết quả) với so that (mục đích) trước khi điền."}]}],"id":"a2-14"},{"n":15,"title":"Indefinite pronouns","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Đại từ phiếm chỉ dùng khi người nói không biết hoặc không cần nêu cụ thể là ai, cái gì, ở đâu. Chúng được ghép theo hệ thống: phần đầu là some, any, no hoặc every, phần sau là -one, -body, -thing hoặc -where. Hai điểm hình thức quan trọng: tất cả đều đi với động từ số ít, và nhóm bắt đầu bằng no đã mang nghĩa phủ định nên không dùng kèm not."},{"p":"Cấu trúc chính: some/any/no/every + -one/-body/-thing/-where"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): Someone left a message, but nobody knows who. (Nói về người hoặc vật không xác định | Phủ định và nghi vấn | Phủ định ngắn gọn)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Nói về người hoặc vật không xác định: Nhóm some dùng trong câu khẳng định. (Someone is waiting for you.)"},{"p":"Phủ định và nghi vấn: Nhóm any dùng trong câu phủ định và câu hỏi. (I didn't see anybody. / Did you hear anything?)"},{"p":"Phủ định ngắn gọn: Nhóm no mang nghĩa phủ định sẵn nên động từ giữ dạng khẳng định. (Nobody came to the meeting.)"},{"p":"Nói về toàn bộ: Nhóm every chỉ tất cả nhưng vẫn đi với động từ số ít. (Everybody was happy.)"},{"p":"Ghi nhớ: Someone, anything, nobody, everywhere ghép từ some, any, no, every với -one, -thing, -where."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: some/any/no/every + -one/-body/-thing/-where"},{"table":[["Nhóm nghĩa","Danh sách từ / Công thức","Ví dụ"],["Người","someone/somebody, anyone/anybody, no one/nobody, everyone/everybody","Everybody knows the answer."],["Vật","something, anything, nothing, everything","Nothing happened."],["Nơi chốn","somewhere, anywhere, nowhere, everywhere","I can't find it anywhere."],["Có tính từ bổ nghĩa","đại từ phiếm chỉ + tính từ (tính từ đứng sau)","something interesting, nothing new"]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Chọn phần đầu theo thể của câu: Some cho câu khẳng định, any cho phủ định và nghi vấn, no cho phủ định ngắn gọn, every cho toàn bộ. (something ↔ anything ↔ nothing)"},{"p":"02. Dùng động từ số ít: Mọi đại từ phiếm chỉ đều kéo theo động từ số ít, kể cả nhóm everybody. (Everybody is here.)"},{"p":"03. Không dùng not với nhóm no: Nobody và nothing đã mang nghĩa phủ định nên động từ ở dạng khẳng định. (Nobody knows, không phải Nobody doesn't know)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Khẳng định và phủ định","Someone left a message, but nobody knows who.\n(Có ai để lại tin nhắn, nhưng không ai biết là ai.)","Someone trong câu khẳng định; nobody đã phủ định nên knows giữ dạng khẳng định."],["Phủ định với any","I didn't see anybody in the office.\n(Tôi không thấy ai trong văn phòng.)","Câu phủ định với didn't thì dùng anybody, không dùng nobody."],["Nghi vấn","Did you hear anything last night?\n(Tối qua bạn có nghe thấy gì không?)","Câu nghi vấn dùng nhóm any."],["Động từ số ít","Everybody in the class is present today.\n(Hôm nay cả lớp đều có mặt.)","Everybody mang nghĩa nhiều người nhưng vẫn đi với động từ số ít is."],["Tính từ đứng sau","I read something interesting about Hue this morning.\n(Sáng nay tôi đọc được một điều thú vị về Huế.)","Khác với danh từ thường, tính từ bổ nghĩa cho đại từ phiếm chỉ thì đứng sau nó."],["Nơi chốn","I looked everywhere but I couldn't find my keys anywhere.\n(Tôi tìm khắp nơi mà vẫn không thấy chìa khoá đâu cả.)","Everywhere trong câu khẳng định, anywhere trong câu phủ định."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Hai cách diễn đạt cùng một ý phủ định"},{"table":[["Cấu trúc","Đặc điểm","Ví dụ"],["not … anybody","động từ phủ định, đại từ nhóm any","I didn't meet anybody."],["… nobody","động từ khẳng định, đại từ nhóm no","I met nobody."],["nobody làm chủ ngữ","động từ số ít, dạng khẳng định","Nobody came."]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: Nobody doesn't know who left the message. → Đã sửa: Nobody knows who left the message. — Nobody đã mang nghĩa phủ định nên không dùng thêm doesn't."},{"p":"Chưa đúng: Everybody are ready. → Đã sửa: Everybody is ready. — Đại từ phiếm chỉ luôn đi với động từ số ít."},{"p":"Chưa đúng: I read interesting something this morning. → Đã sửa: I read something interesting this morning. — Tính từ bổ nghĩa cho đại từ phiếm chỉ thì đứng sau nó."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Phần đầu chọn đúng theo thể của câu."},{"p":"Động từ ở dạng số ít."},{"p":"Nhóm no không dùng kèm not."},{"p":"Tính từ bổ nghĩa đứng sau đại từ phiếm chỉ."}]}],"id":"a2-15"},{"n":16,"title":"A little, a few & a lot of","sections":[{"h":"TRỌNG TÂM","items":[{"p":"Nhóm lượng từ này bổ sung sắc thái cho some và any. A few và a little mang nghĩa tích cực là có một ít, trong khi few và little không có mạo từ mang nghĩa tiêu cực là quá ít, gần như không có. A lot of và plenty of dùng được cho cả hai loại danh từ nên là lựa chọn an toàn khi không chắc."},{"p":"Cấu trúc chính: a few + danh từ số nhiều | a little + danh từ không đếm được"},{"p":"Ví dụ mở đầu (Đọc câu trước khi xem phần phân tích): We have a little time before the train leaves. (Chỉ một lượng nhỏ nhưng đủ dùng | Nhấn mạnh lượng quá ít | Chỉ lượng lớn)"}]},{"h":"CHỨC NĂNG VÀ VÍ DỤ","items":[{"p":"Mỗi chức năng đi kèm một câu mẫu để đối chiếu ngay trong ngữ cảnh."},{"p":"Chỉ một lượng nhỏ nhưng đủ dùng: A few với danh từ đếm được, a little với danh từ không đếm được. (a few friends / a little salt)"},{"p":"Nhấn mạnh lượng quá ít: Bỏ mạo từ a thì nghĩa đổi sang tiêu cực. (He has few friends. / There is little hope.)"},{"p":"Chỉ lượng lớn: A lot of và lots of đi với cả hai loại danh từ; plenty of nhấn mạnh sự dư dả. (a lot of books / a lot of water)"},{"p":"Hỏi và phủ định về lượng: Many và much thường dùng trong câu hỏi và câu phủ định. (Are there many left? / There isn't much time.)"},{"p":"Ghi nhớ: A few đi với danh từ đếm được, a little đi với danh từ không đếm được, a lot of dùng cho cả hai."}]},{"h":"CẤU TRÚC CÂU & MẪU CÂU (CÁC DẠNG THƯỜNG GẶP)","items":[{"p":"Công thức chính: a few + danh từ số nhiều | a little + danh từ không đếm được"},{"table":[["Nhóm lượng từ","Công thức","Ví dụ"],["Đếm được","a few, few, many, several + danh từ số nhiều","a few questions"],["Không đếm được","a little, little, much + danh từ số ít","a little milk"],["Dùng cho cả hai","a lot of, lots of, plenty of, some, any, enough","a lot of time, a lot of friends"],["Sắc thái","a few/a little = có một ít | few/little = quá ít","I have a little money. ↔ I have little money."]]}]},{"h":"TRÌNH TỰ - CÁCH PHÂN TÍCH","items":[{"p":"01. Xác định loại danh từ: Bước này quyết định việc chọn a few hay a little. (a few chairs / a little furniture)"},{"p":"02. Chọn sắc thái tích cực hay tiêu cực: Có mạo từ a thì nghĩa tích cực; bỏ mạo từ thì nghĩa tiêu cực. (a little time ↔ little time)"},{"p":"03. Dùng a lot of cho cả hai loại: A lot of phù hợp với cả hai loại và dùng được trong mọi thể câu. (a lot of people / a lot of rice)"}]},{"h":"VÍ DỤ VÀ GIẢNG GIẢI (ĐỌC MỖI VÍ DỤ THEO BA LỚP: NGHĨA – CẤU TRÚC – NGỮ CẢNH)","items":[{"table":[["Ngữ cảnh","Câu ví dụ & Nghĩa","Cấu trúc"],["Không đếm được, lượng nhỏ","We have a little time before the train leaves.\n(Chúng ta còn một chút thời gian trước khi tàu chạy.)","Time không đếm được nên dùng a little; nghĩa là vẫn còn đủ dùng."],["Đếm được, lượng nhỏ","I invited a few friends to dinner.\n(Tôi mời vài người bạn đến ăn tối.)","Friends đếm được số nhiều nên dùng a few."],["Sắc thái tiêu cực","He has few friends in this city, so he feels lonely.\n(Anh ấy có rất ít bạn ở thành phố này nên thấy cô đơn.)","Few không có mạo từ mang nghĩa quá ít, kéo theo hệ quả tiêu cực ở mệnh đề sau."],["Lượng lớn, đếm được","A lot of students joined the club this year.\n(Năm nay nhiều học sinh tham gia câu lạc bộ.)","A lot of đi với danh từ đếm được số nhiều và động từ số nhiều."],["Lượng lớn, không đếm được","There is a lot of information on the website.\n(Trên trang web có rất nhiều thông tin.)","A lot of cũng đi được với danh từ không đếm được và động từ vẫn ở số ít."],["Phủ định","There isn't much sugar left, but there are still a few biscuits.\n(Không còn nhiều đường, nhưng vẫn còn vài cái bánh.)","Much dùng với sugar trong câu phủ định; a few dùng với biscuits đếm được."]]}]},{"h":"ĐỐI CHIẾU VÀ TỰ SỬA","items":[{"p":"Đối chiếu: Bốn lượng từ gần nghĩa"},{"table":[["Lượng từ","Nghĩa và loại danh từ","Ví dụ"],["a few","một ít, đếm được, nghĩa tích cực","a few days"],["few","quá ít, đếm được, nghĩa tiêu cực","few days"],["a little","một ít, không đếm được, nghĩa tích cực","a little money"],["little","quá ít, không đếm được, nghĩa tiêu cực","little money"]]},{"p":"Tự sửa: Lỗi thường gặp"},{"p":"Chưa đúng: We have a few time. → Đã sửa: We have a little time. — Time không đếm được nên phải dùng a little."},{"p":"Chưa đúng: She has a little friends here. → Đã sửa: She has a few friends here. — Friends đếm được số nhiều nên dùng a few."},{"p":"Chưa đúng: There are a lot of informations. → Đã sửa: There is a lot of information. — Information không đếm được nên không thêm -s và đi với động từ số ít."},{"p":"Tự kiểm tra trước khi làm bài:"},{"p":"Danh từ đi kèm là đếm được hay không đếm được."},{"p":"Sắc thái cần diễn đạt là tích cực hay tiêu cực."},{"p":"Động từ hòa hợp với danh từ chính, không với lượng từ."},{"p":"A lot of được dùng khi không cần phân biệt loại danh từ."}]}],"id":"a2-16"}];
